#!/usr/bin/env node
// scripts/build.mjs — produces `client.js` (do not edit it by hand: edit src/plugin.js and run this).
//
// Concatenates: the header of the DSH module loader + the vendored TipTap bundle
// (vendor/tiptap.iife.js, the dsh-mermaid recipe) + the body of the factory
// (src/plugin.js), wrapped in a safety net: an exception while evaluating
// degrades THIS plugin without breaking the other entries (« Failed to load
// plugins », incident of 23/09).
//
//   node scripts/build.mjs           # (re)write client.js
//   node scripts/build.mjs --check   # exit 1 when client.js is not the build of its sources
//
// test-client.mjs calls assemble() and compares it with the committed client.js.
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')

const indent = (texte, prefixe) => texte.split('\n').map((l) => prefixe + l).join('\n')

/** The text of client.js, built from vendor/tiptap.iife.js and src/plugin.js. */
export const assemble = () => {
  const vendor = readFileSync(join(root, 'vendor', 'tiptap.iife.js'), 'utf8').trimEnd()
  const corps = readFileSync(join(root, 'src', 'plugin.js'), 'utf8')
  return `// @local/kybernos-slides — client bundle GENERATED by scripts/build.mjs (do not edit).
// TipTap 2.27 (MIT) vendored — see vendor/NOTICES.md.
window.__ModuleLoader__.load({
  id: '@local/kybernos-slides/client',
  factory (require) {
    try {
${indent(vendor, '      ')}
      return (function (TipTap) {
${indent(corps, '        ')}
      })(typeof __DSH_TIPTAP_NS !== 'undefined' ? __DSH_TIPTAP_NS : null)
    } catch (error) {
      // An exception here would break the WHOLE entry: degrade, plugin disabled.
      console.error('[kybernos-slides] evaluation failed — plugin disabled', error)
      return { name: 'kybernos-slides/client', inject: [], apply () {} }
    }
  }
})
`
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const out = assemble()
  if (process.argv.includes('--check')) {
    const cur = (() => { try { return readFileSync(join(root, 'client.js'), 'utf8') } catch { return '' } })()
    if (cur !== out) { console.error('client.js is out of date: run node scripts/build.mjs'); process.exit(1) }
    console.log('client.js is up to date')
  } else {
    writeFileSync(join(root, 'client.js'), out)
    console.log('client.js assembled:', out.split('\n').length, 'lines')
  }
}
